/**
 * Build-time sparkline extraction: for every card, downsample ~2.8 s of its
 * primary trace's primary lead into a small normalized polyline, emitted as
 * src/content/sparklines.gen.ts. Run: node tools/gen-sparklines.mjs
 * (re-run whenever a card's primary trace or primary lead changes; the
 * generated file is committed so the app build stays hermetic).
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const REC = resolve(root, 'public/recordings')

// Cheap card scan (avoid a TS runtime): id, traceId, primaryLead per card file.
const cardsDir = resolve(root, 'src/content/cards')
const cards = []
for (const f of readdirSync(cardsDir).filter((f) => f.endsWith('.ts'))) {
  const src = readFileSync(resolve(cardsDir, f), 'utf8')
  const id = src.match(/\bid:\s*'([^']+)'/)?.[1]
  const traceId = src.match(/\btraceId:\s*'([^']+)'/)?.[1]
  const primaryLead = src.match(/\bprimaryLead:\s*'([^']+)'/)?.[1]
  if (id && traceId && primaryLead) cards.push({ id, traceId, primaryLead })
}

const N = 110 // points per sparkline
const WINDOW_MS = 2800

const lines = []
for (const c of cards) {
  let asset
  try {
    asset = JSON.parse(readFileSync(resolve(REC, `${c.traceId}.json`), 'utf8'))
  } catch {
    console.error(`  ! ${c.id}: trace ${c.traceId} missing — skipped`)
    continue
  }
  const samples = asset.leads[c.primaryLead] ?? asset.leads.II
  if (!samples) { console.error(`  ! ${c.id}: no lead`); continue }
  const msPerSample = asset.durationMs / samples.length
  // Start at the first annotated QRS minus a little context, so a beat is visible.
  const firstQrs = asset.annotation?.beats?.[0]?.qrsOn ?? 0
  const t0 = Math.max(0, firstQrs - 320)
  const count = Math.min(samples.length - Math.round(t0 / msPerSample), Math.round(WINDOW_MS / msPerSample))
  const start = Math.round(t0 / msPerSample)
  const win = samples.slice(start, start + count)
  // Downsample with min/max preservation per bucket (keeps QRS spikes).
  const pts = []
  for (let i = 0; i < N; i++) {
    const a = Math.floor((i / N) * win.length)
    const b = Math.max(a + 1, Math.floor(((i + 1) / N) * win.length))
    let lo = Infinity, hi = -Infinity
    for (let j = a; j < b; j++) { lo = Math.min(lo, win[j]); hi = Math.max(hi, win[j]) }
    pts.push(Math.abs(hi) > Math.abs(lo) ? hi : lo)
  }
  const lo = Math.min(...pts), hi = Math.max(...pts)
  const span = hi - lo || 1
  const norm = pts.map((v) => Math.round(((v - lo) / span) * 100) / 100)
  lines.push(`  '${c.id}': [${norm.join(',')}],`)
  console.log(`  ✓ ${c.id} (${c.traceId} · ${c.primaryLead})`)
}

const out = `/** GENERATED by tools/gen-sparklines.mjs — do not edit. Normalized [0,1] primary-lead snippets per card. */
export const SPARKLINES: Record<string, number[]> = {
${lines.join('\n')}
}
`
writeFileSync(resolve(root, 'src/content/sparklines.gen.ts'), out)
console.log(`wrote src/content/sparklines.gen.ts (${lines.length} cards)`)
